const room = bm.room('channel-' + id);
room.on('bm:status', s => { setOnline(s.state === 'open'); if (s.reconnected) reloadMessages(); });
room.on('bm:error', e => showError(e.code === 'not_member' ? 'You are not in this channel' : e.message));
room.on('chat', (msg, from) => append(msg, from));
if (!room.send({ kind: 'chat', text })) markPending(text); // queued until reconnected
